result.output:
{ pkgs, lib, inputs, ... }: let
  # Every agent we care about looks for skills in `<home>/.<tool>/skills/<dir>/SKILL.md`.
  # Each skill in `skills` below is symlinked into every directory listed here.
  agentSkillDirs = [
    ".claude/skills"
    ".codex/skills"
  ];

  # Fetch a skill tarball published to the npm registry. Pin with a sha256 so
  # the lockfile reproduces builds:
  #   { name = "my-skill";
  #     src = skillFromNpm { pname = "@scope/pkg"; version = "1.2.3"; hash = "sha256-..."; }; }
  # Compute the hash with:
  #   nix-prefetch-url --unpack https://registry.npmjs.org/<pname>/-/<basename>-<version>.tgz
  skillFromNpm = { pname, version, hash, subpath ? null }: let
    basename = lib.last (lib.splitString "/" pname);
    tarball = pkgs.fetchzip {
      url = "https://registry.npmjs.org/${pname}/-/${basename}-${version}.tgz";
      inherit hash;
    };
  in if subpath == null then tarball else "${tarball}/${subpath}";

  # Skill list. Each entry installs into every directory in `agentSkillDirs`.
  #
  #   { name = "<directory-name>";
  #     src = <flake input or derivation containing SKILL.md>;
  #     subpath = <optional subdir within src>; }
  #
  # GitHub-sourced skills: declare them as `flake = false` inputs in flake.nix
  # and pass `inputs.<name>` as `src`. Run `nix flake update <name>` to bump.
  #
  # npm-sourced skills: use `skillFromNpm` above.
  skills = [
    {
      name = "code-review-skill";
      src = inputs.code-review-skill;
    }
  ];

  resolveSrc = skill:
    if skill ? subpath && skill.subpath != null
    then "${skill.src}/${skill.subpath}"
    else "${skill.src}";

  skillFiles = lib.listToAttrs (lib.concatMap (skill:
    map (dir: lib.nameValuePair "${dir}/${skill.name}" {
      source = resolveSrc skill;
    }) agentSkillDirs
  ) skills);
in {
  home.file = skillFiles;
}
--- flake.nix
{
  description = "Thomnix WSL2";

  nixConfig = {
    extra-substituters = [ "https://cache.numtide.com" ];
    extra-trusted-public-keys = [ "niks3.numtide.com-1:REDACTED" ];
  };

  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable";
    nixos-wsl.url = "github:nix-community/NixOS-WSL/main";
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    llm-agents.url = "github:numtide/llm-agents.nix";
    dim-unfocused.url = "path:./bespoke/zellij/dim-unfocused";
    mdv = {
      url = "github:WhoSowSee/mdv";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    mdv-previewer = {
      url = "github:WhoSowSee/mdv-previewer.yazi";
      flake = false;
    };
    # Draws mermaid diagrams as text for the yazi markdown preview
    # (scripts/mdv-mermaid.sh). Pinned to a release because the CLI is pre-1.0
    # and still renaming flags. No nixpkgs follows: it is a several-minute Rust
    # build with no binary cache, so let it rebuild only when this tag moves.
    merman.url = "github:Latias94/merman/v0.8.0";

    # Agent skills (SKILL.md format, shared by Claude / Codex / Antigravity).
    # Add new GitHub-sourced skills here as `flake = false` inputs, then
    # reference them from `home/skills.nix`.
    code-review-skill = {
      url = "github:awesome-skills/code-review-skill";
      flake = false;
    };
  };

  outputs = {
    self,
    nixpkgs,
    nixos-wsl,
    home-manager,
    ...
  } @ inputs: let
    inherit (self) outputs;
  in {
    nixosConfigurations = {
      thixos = nixpkgs.lib.nixosSystem {
        specialArgs = {inherit inputs outputs;};
        system = "x86_64-linux";
        modules = [
          nixos-wsl.nixosModules.default
          home-manager.nixosModules.home-manager
          ./nixos/configuration.nix
          {
            system.stateVersion = "25.05";
            wsl.enable = true;
            wsl.defaultUser = "thom";
            wsl.interop.register = true;
          }
        ];
      };
      yoloixos = nixpkgs.lib.nixosSystem {
        specialArgs = {inherit inputs outputs;};
        system = "x86_64-linux";
        modules = [
          nixos-wsl.nixosModules.default
          home-manager.nixosModules.home-manager
          ./nixos/yoloixos.nix
          {
            system.stateVersion = "25.05";
            wsl.enable = true;
            wsl.defaultUser = "agent";
          }
        ];
      };
      seed = nixpkgs.lib.nixosSystem {
        specialArgs = {inherit inputs outputs;};
        system = "x86_64-linux";
        modules = [
          nixos-wsl.nixosModules.default
          home-manager.nixosModules.home-manager
          ./nixos/seed.nix
          {
            system.stateVersion = "25.05";
            wsl.enable = true;
            wsl.defaultUser = "seed";
            wsl.interop.register = true;
          }
        ];
      };
    };
    homeConfigurations = {
      "thom@nix" = home-manager.lib.homeManagerConfiguration {
        pkgs = import nixpkgs {
          system = "x86_64-linux";
          config.allowUnfree = true;
        };
        extraSpecialArgs = { inherit inputs outputs; };
        modules = [
          ./home/home.nix
          {
            home.username = builtins.getEnv "USER";
            home.homeDirectory = builtins.getEnv "HOME";
          }
        ];
      };
      "agent@nix" = home-manager.lib.homeManagerConfiguration {
        pkgs = import nixpkgs {
          system = "x86_64-linux";
          config.allowUnfree = true;
        };
        extraSpecialArgs = { inherit inputs outputs; };
        modules = [
          ./home/agent.nix
          {
            home.username = builtins.getEnv "USER";
            home.homeDirectory = builtins.getEnv "HOME";
          }
        ];
      };
    };
  };
}
